```javascript
const axios = require("axios");

async function getData(input) {
  try {
    const response = await axios.get(
      "https://igram.site/api/instagram",
      {
        params: {
          url: input
        },
        headers: {
          "x-locale": "id"
        }
      }
    );

    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

getData("https://www.instagram.com/reel/Db3nDCRzoGl/?igsh=ajJla2l5azV0Ymxx")
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
```
